mapper.select:
select

c2.C_Name as cName,
d2.D_Name as dName,
c2.C_Abbreviation as cAbbName,
mn.*
from  OA_Notice mn

left join  SYS_Department d2 on mn.D_Id=d2.D_Id
left join  SYS_Company c2 on mn.C_Id=c2.C_Id

    
        and mn.Te_Id = #{params.teId}
    
    
        and mn.N_State=#{params.nState}
    
    
        
            and mn.N_Type=#{params.nType}
        
        
            and substring(mn.N_Type,1,length(#{params.nType})) = #{params.nType}
        
    
    
        and mn.N_KeyWord like concat('%',#{params.nKeyword},'%')
    
    
        and mn.N_Code like concat('%',#{params.N_Code},'%')
    
    
        and mn.N_Title like concat('%',#{params.nTitle},'%')
    
    
        and mn.N_Type in
        
             #{type}
        
    
    
        and (
        
            mn.specific_scopeid like concat('%',#{specificScopeid},'%')
        
        
            or mn.range_type = #{params.rangeType}
        
        
            or mn.n_create_uid = #{params.nCreateUid}
        
        )
    


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by mn.priority,mn.N_Create_Time desc

select

c2.C_Name as cName,
d2.D_Name as dName,
c2.C_Abbreviation as cAbbName,
mn.*
from  OA_Notice mn

left join  SYS_Department d2 on mn.D_Id=d2.D_Id
left join  SYS_Company c2 on mn.C_Id=c2.C_Id
where mn.N_Id not in (select distinct N_Id from  OA_Notice_Read where N_Id is not null and  Nr_Uid=#{params.userId})

    and mn.Te_Id = #{params.teId}


    
        and mn.N_Type=#{params.nType}
    
    
        and substring(mn.N_Type,1,length(#{params.nType})) = #{params.nType}
    


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by mn.priority,mn.N_Create_Time desc
